/* Shipping apps (Settings > Integrations: Shippo, EasyPost, ShipStation). A label bought from an order with Shippo or EasyPost is kept on that order: the provider's ids, the carrier and service, the tracking number, the label's https PDF, what it cost the seller (never charged to the buyer), test or live, and whether it was voided; one label per quoted provider shipment, so two presses of Buy never buy two. Server only, as the other order tables are. And the job queue takes any well formed job kind, so ShipStation's shipstation_push and shipstation_sync (and other new kinds) are let in: the old fixed list refused them. No rows change. Needs part 78. Until it runs, Buy a label says labels turn on after this part and nothing is bought; ShipStation orders are not sent. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.shipping_labels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, checkout_id uuid NOT NULL REFERENCES public.commerce_checkouts(id) ON DELETE CASCADE, fulfillment_id uuid REFERENCES public.fulfillments(id) ON DELETE SET NULL, provider text NOT NULL CHECK (provider IN ('shippo', 'easypost')), provider_shipment_id text NOT NULL CHECK (char_length(provider_shipment_id) BETWEEN 1 AND 120), provider_label_id text NOT NULL CHECK (char_length(provider_label_id) BETWEEN 1 AND 120), carrier text CHECK (carrier IS NULL OR char_length(carrier) <= 60), service text CHECK (service IS NULL OR char_length(service) <= 120), tracking_number text CHECK (tracking_number IS NULL OR char_length(tracking_number) <= 80), label_url text CHECK (label_url IS NULL OR (char_length(label_url) <= 2000 AND label_url LIKE 'https://%')), cost_cents integer NOT NULL DEFAULT 0 CHECK (cost_cents BETWEEN 0 AND 100000000), currency text NOT NULL DEFAULT 'USD' CHECK (currency ~ '^[A-Z]{3}$'), package jsonb CHECK (package IS NULL OR (jsonb_typeof(package) = 'object' AND pg_column_size(package) <= 1024)), test_mode boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'buying' CHECK (status IN ('buying', 'purchased', 'void_pending', 'voided', 'void_rejected')), voided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS shipping_labels_shipment_key ON public.shipping_labels (provider, provider_shipment_id);
CREATE INDEX IF NOT EXISTS shipping_labels_checkout_idx ON public.shipping_labels (checkout_id, created_at);
CREATE INDEX IF NOT EXISTS shipping_labels_creator_idx ON public.shipping_labels (creator_id, created_at DESC);
CREATE INDEX IF NOT EXISTS shipping_labels_fulfillment_idx ON public.shipping_labels (fulfillment_id) WHERE fulfillment_id IS NOT NULL;
ALTER TABLE public.shipping_labels ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.shipping_labels FROM anon, authenticated;
GRANT ALL ON public.shipping_labels TO service_role;
ALTER TABLE public.commerce_jobs DROP CONSTRAINT IF EXISTS commerce_jobs_kind_check;
ALTER TABLE public.commerce_jobs ADD CONSTRAINT commerce_jobs_kind_check CHECK (kind ~ '^[a-z][a-z0-9_]{2,39}$') NOT VALID;
notify pgrst, 'reload schema';
